import Foundation

public enum FileChangeStatus: String, Codable, Sendable, CaseIterable {
    case created = "Created"
    case modified = "Modified"
    case unchanged = "Unchanged"
}

public enum TargetFramework: String, Codable, Sendable, CaseIterable {
    case swiftUI = "SwiftUI"
    case uiKit = "UIKit"
    case designTokens = "DesignTokens"
    case assetCatalog = "AssetCatalog"
}

/// Represents a source file or asset generated by the DesignPilot engine.
public struct GeneratedFile: Identifiable, Codable, Sendable, Hashable {
    public var id: String { relativePath }
    public let relativePath: String
    public let content: String
    public let status: FileChangeStatus
    public let framework: TargetFramework
    public let existingContent: String?
    public let checksum: String

    public init(
        relativePath: String,
        content: String,
        status: FileChangeStatus,
        framework: TargetFramework,
        existingContent: String? = nil
    ) {
        self.relativePath = relativePath
        self.content = content
        self.status = status
        self.framework = framework
        self.existingContent = existingContent
        self.checksum = GeneratedFile.calculateChecksum(content)
    }

    public var sizeInBytes: Int {
        content.utf8.count
    }

    public var fileName: String {
        (relativePath as NSString).lastPathComponent
    }

    public var lineCount: Int {
        content.components(separatedBy: .newlines).count
    }

    private static func calculateChecksum(_ string: String) -> String {
        var hash = UInt64(5381)
        for byte in string.utf8 {
            hash = 127 * (hash & 0x00FFFFFFFFFFFFFF) + UInt64(byte)
        }
        return String(format: "%016llx", hash)
    }
}
